const BASE = new URL('./', self.location).href;
const SCOPE = new URL(BASE).pathname;
const WARM = '__warm/';       // a marker in the cache: this group was kept offline
const href = (p) => new URL(p, BASE).href;
const pathOf = (u) => {
  const x = new URL(u);
  if (x.origin !== self.location.origin || !x.pathname.startsWith(SCOPE)) return null;
  const p = x.pathname.slice(SCOPE.length);
  return p === '' || p === 'index.html' ? './' : p;
};

/** The file a device keeps for `p`: a picture's AVIF twin where it shows AVIF. */
const pick = (p, format) => (format === 'avif' && p.endsWith('.webp') && HASH[p.slice(0, -5) + '.avif'] ? p.slice(0, -5) + '.avif' : p);

/** A response as kept: with the content hash of the file it is, to tell later whether it is still current. */
const stamped = (p, res) => res.blob().then((body) => {
  const headers = new Headers(res.headers);
  headers.set('x-kp-hash', HASH[p]);
  return new Response(body, { status: res.status, statusText: res.statusText, headers });
});

async function older() {
  const keys = (await caches.keys()).filter((k) => k.startsWith('kids-playground-') && k !== CACHE);
  return Promise.all(keys.map((k) => caches.open(k)));
}

/** Every file of `paths` in the cache: from an older cache when it has the same file, else downloaded. */
async function fill(cache, paths, olds = []) {
  const todo = [];
  for (const p of paths) if (!(await cache.match(href(p)))) todo.push(p);
  let i = 0;
  const worker = async () => {
    while (i < todo.length) {
      const p = todo[i++];
      let res = null;
      for (const o of olds) {
        const r = await o.match(href(p));
        if (r && r.headers.get('x-kp-hash') === HASH[p]) { res = r; break; }
      }
      try {
        if (!res) { res = await fetch(href(p), { cache: 'no-cache' }); if (!res.ok) continue; res = await stamped(p, res); }
        await cache.put(href(p), res);
      } catch { /* offline or gone: it is fetched when it is used */ }
    }
  };
  await Promise.all(Array.from({ length: 6 }, worker));
}

async function warm(name, format, olds = []) {
  if (!GROUPS[name]) return;
  const cache = await caches.open(CACHE);
  await fill(cache, GROUPS[name].map((p) => pick(p, format)), olds);
  await cache.put(href(WARM + name), new Response(format || 'webp'));      // the marker remembers the format
}

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE), olds = await older();
    await fill(cache, CORE, olds);
    // whatever an older version kept and is unchanged comes along (no download); the games it kept offline are
    // completed after activation
    for (const o of olds) {
      for (const req of await o.keys()) {
        const p = pathOf(req.url);
        if (p && p.startsWith(WARM)) { await cache.put(req, await o.match(req)); continue; }
        if (!p || !HASH[p] || (await cache.match(req))) continue;
        const r = await o.match(req);
        if (r && r.headers.get('x-kp-hash') === HASH[p]) await cache.put(req, r);
      }
    }
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    await self.clients.claim();
    const cache = await caches.open(CACHE);
    for (const req of await cache.keys()) {
      const p = pathOf(req.url);
      if (p && p.startsWith(WARM)) await warm(p.slice(WARM.length), await (await cache.match(req)).text());
    }
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith('kids-playground-') && k !== CACHE).map((k) => caches.delete(k)));
  })());
});

// the page says which game (or the salon lobby, or the album) it opened: keep all of it offline
self.addEventListener('message', (event) => {
  const name = event.data && event.data.warm;
  if (typeof name === 'string') event.waitUntil(warm(name, event.data.format));
});

self.addEventListener('fetch', (event) => {
  const request = event.request, p = request.method === 'GET' ? pathOf(request.url) : null;
  if (!p) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const hit = await cache.match(p === './' ? href('./') : request, { ignoreSearch: true });
    if (hit) return hit;
    const res = await fetch(request);
    if (res.ok && HASH[p] && request.mode !== 'navigate') cache.put(href(p), await stamped(p, res.clone())).catch(() => {});
    return res;
  })());
});
